// Proves the migrated gameplay engine behaves EXACTLY like the original one.
//
// tests/fixtures/engine-golden.json was generated by running the ORIGINAL engine.js (Santa-Safe-Catch @ ce31832) on
// eight seeds with a scripted player. These tests re-run the same games through the migrated engine and require
// identical scores, catch counts, durations, mid-game snapshots, constants and difficulty curves.
import { describe, expect, it } from 'vitest';
import golden from './fixtures/engine-golden.json';
import { Sim, CFG, replay } from '../src/game/engine.js';
import * as serverEngine from '../supabase/functions/_shared/engine.js';

describe('engine constants (original values)', () => {
  it.each(Object.entries(golden.consts))('CFG.%s', (k, v) => { expect(CFG[k]).toBe(v); });
});

describe('difficulty curves (original formulas)', () => {
  it.each(Object.entries(golden.curves))('t = %s s', (t, want) => {
    const tt = Number(t);
    for (const fn of ['fall', 'interval', 'jump', 'coalChance', 'goldChance', 'phonePts']) expect(CFG[fn](tt)).toBeCloseTo(want[fn], 12);
  });
});

describe('deterministic replay (the anti-cheat model)', () => {
  it.each(golden.games.map((g) => [g.seed, g]))('seed %s: identical score / catches / duration', (_seed, g) => {
    const r = replay(g.seed, g.inputs, g.endTick, 60 * 60 * 45);
    expect(r.score).toBe(g.expect.score);
    expect(r.caught).toBe(g.expect.caught);
    expect(r.ticks).toBe(g.expect.ticks);
    expect(r.t).toBe(g.expect.t);
    expect(r.over).toBe(g.expect.over);
  });

  it.each(golden.games.map((g) => [g.seed, g]))('seed %s: identical mid-game world state', (_seed, g) => {
    const sim = new Sim(g.seed); let k = 0;
    while (!sim.over && sim.tick < 3001) {
      while (k < g.inputs.length && g.inputs[k] <= sim.tick + 1) { sim.setTarget(g.inputs[k + 1]); k += 2; }
      sim.step();
      const snap = g.snaps[sim.tick];
      if (snap) {
        expect(+sim.x.toFixed(6)).toBe(snap.x);
        expect(sim.lives).toBe(snap.lives);
        expect(sim.score).toBe(snap.score);
        expect(sim.items.length).toBe(snap.items);
        expect(sim.items.map((i) => +i.y.toFixed(4)).slice(0, 6)).toEqual(snap.ys);
      }
    }
  });

  it('a different seed gives a different game (the seed really drives the spawns)', () => {
    const a = new Sim(1), b = new Sim(2);
    for (let i = 0; i < 600; i++) { a.step(); b.step(); }
    expect(a.items.map((i) => i.x)).not.toEqual(b.items.map((i) => i.x));
  });

  it('the browser and the server validator use the very same engine module', () => {
    expect(serverEngine.Sim).toBe(Sim);
    expect(serverEngine.replay).toBe(replay);
    expect(serverEngine.CFG).toBe(CFG);
  });

  it('replaying with tampered inputs changes the outcome (so a faked score cannot be replayed)', () => {
    const g = golden.games[0];
    const tampered = g.inputs.map((v, i) => (i % 2 === 1 ? v + 80 : v));
    const r = replay(g.seed, tampered, g.endTick, 60 * 60 * 45);
    expect(r.score).not.toBe(g.expect.score);
  });
});
